# Update Project total_costing_amount when Timesheet is submitted
# Check if any timesheet details have a project
project_costs = {}

for detail in doc.time_logs:
	if detail.project:
		if detail.project not in project_costs:
			project_costs[detail.project] = 0

		# Add costing amount for this detail
		if detail.costing_amount:
			project_costs[detail.project] += detail.costing_amount

# Update each project
for project_name, cost in project_costs.items():
	if cost > 0:
		project = frappe.get_doc("Project", project_name)

		# Add to existing costing amount
		current_cost = project.get("total_costing_amount") or 0
		project.total_costing_amount = current_cost + cost

		# Save without triggering events
		project.flags.ignore_validate_update_after_submit = True
		project.save(ignore_permissions=True)

		frappe.msgprint(f"Updated project {project_name} cost by {cost}")
